  while p*p<=x:
   if x%p==0:
    k=0
    while x%p==0:
     x//=p; k+=1
    f.append((p,k)); primes.add(p)
   p+=1
  if x>1:
   f.append((x,1)); primes.add(x)
  facs.append(dict(f))
 ans=1
 for p in primes:
  ds=[f.get(p,0) for f in facs]
  maxh=sum(ds)
  powers=[1]*(maxh+1)
  for i in range(1,maxh+1):
   powers[i]=powers[i-1]*p%MOD
  dp={0:1}
  t=1
  for k in ds:
   if k==0:
    dp={h:v*powers[h]%MOD for h,v in dp.items()}
   else:
    nd={}
    for h,v in dp.items():
     # numerator contains the prime: raw valuation decreases by k
     z=h-k
     if z<0:
      drop=-z
      nh=0
      val=v*pow(p,drop*t,MOD)%MOD
     else:
      nh=z
      val=v
     val=val*powers[nh]%MOD
     nd[nh]=(nd.get(nh,0)+val)%MOD
     # denominator contains the prime: raw valuation increases by k
     nh=h+k
     val=v*powers[nh]%MOD
     nd[nh]=(nd.get(nh,0)+val)%MOD
    dp=nd
   t+=1
  ans=ans*sum(dp.values())%MOD
 print(ans)

