import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    mx = max(a)

    spf = list(range(mx + 1))
    for p in range(2, int(mx ** 0.5) + 1):
        if spf[p] == p:
            for q in range(p * p, mx + 1, p):
                if spf[q] == q:
                    spf[q] = p

    phi = list(range(mx + 1))
    for p in range(2, mx + 1):
        if spf[p] == p:
            for q in range(p, mx + 1, p):
                phi[q] -= phi[q] // p

    # F[d] is the sum of 2^(i-1) for earlier positions i with d | A_i.
    F = [0] * (mx + 1)
    weight = 1
    ans = 0
    out = []

    for x in a:
        factors = []
        y = x
        while y > 1:
            p = spf[y]
            e = 0
            while y % p == 0:
                y //= p
                e += 1
            factors.append((p, e))

        divisors = [1]
        for p, e in factors:
            old = divisors[:]
            mul = 1
            for _ in range(e):
                mul *= p
                divisors.extend(d * mul for d in old)

        contribution = 0
        for d in divisors:
            contribution += phi[d] * F[d]
        ans = (2 * ans + contribution) % MOD
        out.append(str(ans))

        for d in divisors:
            value = F[d] + weight
            F[d] = value - MOD if value >= MOD else value
        weight = weight * 2 % MOD

    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

