from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, idx))

        largest = second = 0
        largest_id = -1
        base = 0
        gain = [0] * len(conflictingPairs)

        for right in range(1, n + 1):
            for left, idx in by_right[right]:
                if left > largest:
                    second, largest, largest_id = largest, left, idx
                elif left > second:
                    second = left

            base += right - largest
            if largest_id >= 0:
                gain[largest_id] += largest - second

        return base + max(gain)

