class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # A number x > 1 takes one operation to become popcount(x),
        # followed by the reductions needed for that popcount to reach 1.
        good = [False] * (n + 1)
        for r in range(1, n + 1):
            t = r
            steps = 0
            while t != 1:
                t = t.bit_count()
                steps += 1
            good[r] = steps <= k - 1

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i % MOD
        inv_fact = [1] * (n + 1)
        inv_fact[n] = pow(fact[n], MOD - 2, MOD)
        for i in range(n, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % MOD

        def choose(a: int, b: int) -> int:
            if b < 0 or b > a:
                return 0
            return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

        ans = 0
        ones_before = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                for weight in range(1, n + 1):
                    if good[weight]:
                        need = weight - ones_before
                        if 0 <= need <= remaining:
                            ans += choose(remaining, need)
                ones_before += 1
        return ans % MOD

