import sys, heapq

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    g = [row.decode() for row in data[1:1 + n]]

    inc = [[[] for _ in range(26)] for _ in range(n)]
    out = [[[] for _ in range(26)] for _ in range(n)]
    for i, row in enumerate(g):
        for j, ch in enumerate(row):
            if ch != '-':
                c = ord(ch) - 97
                out[i][c].append(j)
                inc[j][c].append(i)

    inf = 10**9
    dist = [[inf] * n for _ in range(n)]
    heap = []
    reached = 0
    max_dist = 0

    # A palindrome has an even-length center at one vertex, or an
    # odd-length center consisting of one edge.
    for i in range(n):
        dist[i][i] = 0
        reached += 1
        heapq.heappush(heap, (0, i * n + i))
    for i, row in enumerate(g):
        for j, ch in enumerate(row):
            if ch != '-' and dist[i][j] > 1:
                dist[i][j] = 1
                reached += 1
                max_dist = 1
                heapq.heappush(heap, (1, i * n + j))

    while heap:
        w, z = heapq.heappop(heap)
        u, v = divmod(z, n)
        if dist[u][v] != w:
            continue
        new_w = w + 2
        # Every pair is already reachable with distance at most new_w.
        if reached == n * n and max_dist <= new_w:
            break
        for c in range(26):
            for x in inc[u][c]:
                dx = dist[x]
                for y in out[v][c]:
                    if new_w < dx[y]:
                        if dx[y] == inf:
                            reached += 1
                        dx[y] = new_w
                        max_dist = max(max_dist, new_w)
                        heapq.heappush(heap, (new_w, x * n + y))

    print('\n'.join(' '.join(str(-1 if x == inf else x) for x in row)
                    for row in dist))

solve()

