import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[0], data[1]
    rows = [0] * n
    k = 2
    for _ in range(m):
        u, v = data[k] - 1, data[k + 1] - 1
        k += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduced row echelon form of the adjacency matrix over GF(2).
    pivots = []
    r = 0
    for c in range(n):
        q = next((i for i in range(r, n) if (rows[i] >> c) & 1), None)
        if q is None:
            continue
        rows[r], rows[q] = rows[q], rows[r]
        for i in range(n):
            if i != r and ((rows[i] >> c) & 1):
                rows[i] ^= rows[r]
        pivots.append(c)
        r += 1

    pivot_set = set(pivots)
    free = [c for c in range(n) if c not in pivot_set]
    values = [0] * n
    for j, f in enumerate(free):
        bit = 1 << j
        values[f] |= bit
        for i, c in enumerate(pivots):
            if (rows[i] >> f) & 1:
                values[c] |= bit

    if any(x == 0 for x in values):
        print('No')
    else:
        print('Yes')
        print(*values)

