from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        def completions(odds_left: int, evens_left: int, first_parity):
            length = odds_left + evens_left
            if length == 0:
                return 1
            starts = (0, 1) if first_parity is None else (first_parity,)
            patterns = 0
            for start in starts:
                odd_positions = (length + 1) // 2 if start == 1 else length // 2
                if odd_positions == odds_left and length - odd_positions == evens_left:
                    patterns += 1
            return patterns * fact[odds_left] * fact[evens_left]

        total_odds = (n + 1) // 2
        total_evens = n // 2
        used = set()
        answer = []
        previous_parity = None
        used_odds = used_evens = 0

        for position in range(n):
            selected = None
            for value in range(1, n + 1):
                if value in used:
                    continue
                parity = value % 2
                if previous_parity is not None and parity == previous_parity:
                    continue

                odds_left = total_odds - used_odds - (parity == 1)
                evens_left = total_evens - used_evens - (parity == 0)
                remaining = n - position - 1
                first = 1 - parity if remaining else None
                count = completions(odds_left, evens_left, first)
                if k > count:
                    k -= count
                else:
                    selected = value
                    break

            if selected is None:
                return []
            used.add(selected)
            answer.append(selected)
            previous_parity = selected % 2
            if previous_parity:
                used_odds += 1
            else:
                used_evens += 1

        return answer

