class Solution:
 def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
  blocks=deque(); cost=0; r=len(nums)-1; ans=0
  for i in range(len(nums)-1,-1,-1):
   x=nums[i]; cnt=1
   while blocks and blocks[0][0] < x:
    v,c=blocks.popleft(); cost+=(x-v)*c; cnt+=c
   blocks.appendleft((x,cnt))
   while cost>k:
    v,c=blocks.pop(); cost-=v-nums[r]; r-=1
    if c>1: blocks.append((v,c-1))
   ans+=r-i+1
  return ans

